# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print the results
print("Optimization Status:", pulp.LpStatus[model.status])
print("Total Transmission Loss Cost:", pulp.value(model.objective))

print("\nOptimal Power Flows (MW):")
for plant in plants:
    for hub in hubs:
        if flow[plant][hub].varValue > 0:
            print(f"From {plant} to {hub}: {flow[plant][hub].varValue:.2f} MW")
